using namespace std;

using ll = long long;
using PII = pair<int, int>;
using PLL = pair<ll, ll>;

ll fast_pow(ll b, ll e, ll m) {
    ll r = 1;
    b %= m;
    while (e) {
        if (e & 1) r = (r * b) % m;
        b = (b * b) % m;
        e >>= 1;
    }
    return r % m;
}

