    string output;
    bool at_replaced = false;
    int n = input.size();

    for (int i = 0; i < n; i++) {
        if (i > 0 && i + 2 < n) {
            if (input[i] == 'd' && input[i+1] == 'o' && input[i+2] == 't') {
                output += '.';
